/**
 * @see \App\Http\Controllers\Retailer\ApplicationActionController::rejectedApplicationsWithOtherReason()
 */
#[Test]
public function rejected_by_other_reason_list_is_scoped_to_the_acting_retailer_and_to_other_reason_decisions(): void
{
    // Arrange
    $retailerUser = RetailerUser::factory()->create();
    Passport::actingAs($retailerUser, [], 'retailer');

    $expected = Application::factory()
        ->v4()
        ->count(2)
        ->withRetailer($retailerUser->retailer)
        ->withOrder()
        ->rejected()
        ->withRejectionDecisionType(OtherReasonsRejectionSpecification::class)
        ->create([
            'retailer_user_id' => $retailerUser->id,
        ]);

    // Near miss: same retailer, rejected, but the last decision has another specification type.
    Application::factory()
        ->v4()
        ->withRetailer($retailerUser->retailer)
        ->withOrder()
        ->rejected()
        ->withRejectionDecisionType(HighAmountRequestedSpecification::class)
        ->create([
            'retailer_user_id' => $retailerUser->id,
        ]);

    // Near miss: another retailer, rejected for other reasons.
    $otherRetailerUser = RetailerUser::factory()->create();

    Application::factory()
        ->v4()
        ->withRetailer($otherRetailerUser->retailer)
        ->withOrder()
        ->rejected()
        ->withRejectionDecisionType(OtherReasonsRejectionSpecification::class)
        ->create([
            'retailer_user_id' => $otherRetailerUser->id,
        ]);

    // Act
    $response = $this->getJson(route('retailer.rejected-by-other-reason-applications'));

    // Assert
    $response->assertStatus(200)
        ->assertJsonCount(2, 'data');

    $this->assertEqualsCanonicalizing(
        $expected->pluck('id')->all(),
        collect($response->json('data'))->pluck('id')->all(),
    );
}

/**
 * @see \App\Http\Controllers\Retailer\ApplicationActionController::rejectedApplicationsWithOtherReason()
 */
#[Test]
public function rejected_by_other_reason_list_includes_a_decision_exactly_at_the_seven_day_cutoff(): void
{
    // Arrange
    $retailerUser = RetailerUser::factory()->create();
    Passport::actingAs($retailerUser, [], 'retailer');

    $cutoff = now()->startOfDay()->subWeek();

    $included = Application::factory()
        ->v4()
        ->withRetailer($retailerUser->retailer)
        ->withOrder()
        ->rejected()
        ->withRejectionDecisionType(
            decision: OtherReasonsRejectionSpecification::class,
            attributes: [
                'created_at' => $cutoff->copy(),
                'updated_at' => $cutoff->copy(),
            ],
        )
        ->create([
            'retailer_user_id' => $retailerUser->id,
        ]);

    Application::factory()
        ->v4()
        ->withRetailer($retailerUser->retailer)
        ->withOrder()
        ->rejected()
        ->withRejectionDecisionType(
            decision: OtherReasonsRejectionSpecification::class,
            attributes: [
                'created_at' => $cutoff->copy()->subSecond(),
                'updated_at' => $cutoff->copy()->subSecond(),
            ],
        )
        ->create([
            'retailer_user_id' => $retailerUser->id,
        ]);

    // Act
    $response = $this->getJson(route('retailer.rejected-by-other-reason-applications'));

    // Assert
    $response->assertStatus(200)
        ->assertJsonCount(1, 'data')
        ->assertJsonPath('data.0.id', $included->id);
}

/**
 * @see \App\Http\Controllers\Retailer\ApplicationActionController::rejectedApplicationsWithOtherReason()
 */
#[Test]
public function rejected_by_other_reason_list_follows_the_latest_decision_of_an_application(): void
{
    // Arrange
    $retailerUser = RetailerUser::factory()->create();
    Passport::actingAs($retailerUser, [], 'retailer');

    // The other-reason rejection is the latest decision: expected in the list.
    $included = Application::factory()
        ->v4()
        ->withRetailer($retailerUser->retailer)
        ->withOrder()
        ->rejected()
        ->withRejectionDecisionType(
            decision: HighAmountRequestedSpecification::class,
            attributes: [
                'created_at' => now()->subDays(2),
                'updated_at' => now()->subDays(2),
            ],
        )
        ->withRejectionDecisionType(
            decision: OtherReasonsRejectionSpecification::class,
            attributes: [
                'created_at' => now()->subDay(),
                'updated_at' => now()->subDay(),
            ],
        )
        ->create([
            'retailer_user_id' => $retailerUser->id,
        ]);

    // The other-reason rejection was superseded by a newer decision: expected to be absent.
    Application::factory()
        ->v4()
        ->withRetailer($retailerUser->retailer)
        ->withOrder()
        ->rejected()
        ->withRejectionDecisionType(
            decision: OtherReasonsRejectionSpecification::class,
            attributes: [
                'created_at' => now()->subDays(2),
                'updated_at' => now()->subDays(2),
            ],
        )
        ->withRejectionDecisionType(
            decision: HighAmountRequestedSpecification::class,
            attributes: [
                'created_at' => now()->subDay(),
                'updated_at' => now()->subDay(),
            ],
        )
        ->create([
            'retailer_user_id' => $retailerUser->id,
        ]);

    // Act
    $response = $this->getJson(route('retailer.rejected-by-other-reason-applications'));

    // Assert
    $response->assertStatus(200)
        ->assertJsonCount(1, 'data')
        ->assertJsonPath('data.0.id', $included->id);
}

